/**
 * Generates supabase/seed.sql from the Phase 1 menu + settings files.
 * Run:  node scripts/generate-seed.ts   (Node 24 runs TypeScript directly)
 * Re-running seed.sql is safe: it upserts by id and won't touch orders.
 */
import { writeFileSync } from "node:fs";
import { categories, products } from "../lib/data/menu.ts";
import { defaultSettings } from "../lib/data/settings.ts";

const q = (v: string | null | undefined) => (v === null || v === undefined ? "null" : `'${v.replace(/'/g, "''")}'`);
const b = (v: boolean) => (v ? "true" : "false");
const lines: string[] = [
  "-- Generated by scripts/generate-seed.ts — menu from public/menu-reference.png + confirmed decisions.",
  "begin;",
  "",
];

for (const [i, c] of categories.entries()) {
  lines.push(
    `insert into public.categories (id, name, blurb, sort) values (${q(c.id)}, ${q(c.name)}, ${q(c.blurb)}, ${i})`,
    `  on conflict (id) do update set name = excluded.name, blurb = excluded.blurb, sort = excluded.sort;`,
  );
}
lines.push("");

for (const [i, p] of products.entries()) {
  lines.push(
    `insert into public.products (id, category_id, name, description, price_cents, image_url, image_alt, image_is_placeholder, popular, sort)`,
    `  values (${q(p.id)}, ${q(p.categoryId)}, ${q(p.name)}, ${q(p.description ?? null)}, ${p.priceCents}, ${q(p.image?.src ?? null)}, ${q(p.image?.alt ?? null)}, ${b(p.image?.isPlaceholder ?? false)}, ${b(!!p.popular)}, ${i})`,
    `  on conflict (id) do update set category_id = excluded.category_id, name = excluded.name, description = excluded.description,`,
    `    price_cents = excluded.price_cents, image_url = excluded.image_url, image_alt = excluded.image_alt,`,
    `    image_is_placeholder = excluded.image_is_placeholder, popular = excluded.popular, sort = excluded.sort, archived = false;`,
  );
}
lines.push("");

// Options reference other products (combo drinks), so they go in after all products exist.
lines.push("-- Rebuild option groups so removed options (e.g. biscuit) disappear.");
lines.push(`delete from public.option_groups where product_id in (${products.map((p) => q(p.id)).join(", ")});`);
for (const p of products) {
  for (const [gi, g] of p.optionGroups.entries()) {
    lines.push(
      `with g as (insert into public.option_groups (product_id, key, label, hint, required, max_select, sort)`,
      `  values (${q(p.id)}, ${q(g.id)}, ${q(g.label)}, ${q(g.hint ?? null)}, ${b(g.required)}, ${g.max}, ${gi}) returning id)`,
      `insert into public.options (group_id, key, label, price_delta_cents, linked_product_id, sort) select g.id, v.key, v.label, v.delta, v.linked, v.sort from g, (values`,
      g.options
        .map((o, oi) => `  (${q(o.id)}, ${q(o.label)}, ${o.priceDeltaCents}, ${q(o.productId ?? null)}, ${oi})`)
        .join(",\n") + `) as v(key, label, delta, linked, sort);`,
    );
  }
}
lines.push("");

for (const p of products) {
  lines.push(
    `insert into public.product_availability (product_id, is_available) values (${q(p.id)}, ${b(p.id !== "chai-latte")}) on conflict (product_id) do nothing;`,
  );
}
lines.push("");

const s = defaultSettings;
lines.push(
  `insert into public.store_settings (id, ordering_paused, pause_message, order_cutoff, enforce_cutoff, timezone, pickup_enabled, pickup_location, delivery_enabled, delivery_fee_cents, require_room, hours, hours_note, contact)`,
  `  values (1, ${b(s.orderingPaused)}, ${q(s.pauseMessage)}, ${q(s.orderCutoff)}, ${b(s.enforceCutoff)}, ${q(s.timezone)}, ${b(s.pickup.enabled)}, ${q(s.pickup.location)}, ${b(s.delivery.enabled)}, ${s.delivery.feeCents}, ${b(s.delivery.requireRoom)},`,
  `    ${q(JSON.stringify(s.hours))}::jsonb, ${q(s.hoursNote)}, ${q(JSON.stringify(s.contact))}::jsonb)`,
  `  on conflict (id) do nothing;`,
  "",
);
for (const [i, w] of s.windows.entries()) {
  lines.push(
    `insert into public.fulfillment_windows (id, label, detail, pickup, delivery, capacity, sort) values (${q(w.id)}, ${q(w.label)}, ${q(w.detail)}, ${b(w.pickup)}, ${b(w.delivery)}, ${w.capacity ?? "null"}, ${i}) on conflict (id) do nothing;`,
  );
}
lines.push("", "commit;", "");

writeFileSync(new URL("../supabase/seed.sql", import.meta.url), lines.join("\n"));
console.log("Wrote supabase/seed.sql");
